cards.content:
Module-module dasar dan keranjang:

```javascript run
// === config.js ===
export const PAJAK = 0.1;
// === menu.js ===
const daftar = { kopi: 18000, teh: 12000, roti: 15000 };
export function hargaMenu(nama) {
  if (!(nama in daftar)) throw new Error(`Menu ${nama} tidak ada`);
  return daftar[nama];
}
// === keranjang.js ===
import { hargaMenu } from "./menu.js";
const isi = new Map();
export function tambah(nama, qty = 1) {
  hargaMenu(nama);
  isi.set(nama, (isi.get(nama) ?? 0) + qty);
}
export function item() {
  return [...isi].map(([nama, qty]) => ({ nama, qty, subtotal: hargaMenu(nama) * qty }));
}
// === main.js ===
import { tambah, item } from "./keranjang.js";
tambah("kopi", 2);
tambah("roti");
tambah("kopi");
try {
  tambah("es");
} catch (e) {
  console.log(e.message);
}
console.log(item());
```

Hasil di console:

```text
Menu es tidak ada
[ { nama: 'kopi', qty: 3, subtotal: 54000 }, { nama: 'roti', qty: 1, subtotal: 15000 } ]
```

- Isi keranjang disimpan di `Map` yang **tidak di-export**. Satu-satunya cara mengubahnya adalah lewat `tambah`.
- `tambah` memanggil `hargaMenu` dulu, supaya menu yang tidak ada langsung ditolak sebelum masuk keranjang.
- Menambah menu yang sama menjumlahkan qty-nya.

Module struk menggabungkan data keranjang, format, dan konstanta:

```javascript run
// === config.js ===
export const PAJAK = 0.1;
// === format.js ===
export const rp = (n) => "Rp" + n.toLocaleString("id-ID");
// === struk.js ===
import { PAJAK } from "./config.js";
import { rp } from "./format.js";
export function hitungTotal(item) {
  const subtotal = item.reduce((t, i) => t + i.subtotal, 0);
  const pajak = Math.round(subtotal * PAJAK);
  return { subtotal, pajak, total: subtotal + pajak };
}
export function cetakStruk(item) {
  for (const i of item) console.log(`${i.nama} x${i.qty}`.padEnd(12) + rp(i.subtotal));
  const t = hitungTotal(item);
  console.log("Pajak".padEnd(12) + rp(t.pajak));
  console.log("TOTAL".padEnd(12) + rp(t.total));
}
// === main.js ===
import { cetakStruk } from "./struk.js";
cetakStruk([{ nama: "kopi", qty: 3, subtotal: 54000 }, { nama: "roti", qty: 1, subtotal: 15000 }]);
```

Hasil di console:

```text
kopi x3     Rp54.000
roti x1     Rp15.000
Pajak       Rp6.900
TOTAL       Rp75.900
```

- `hitungTotal` adalah function **murni**: masukannya array item, hasilnya object angka. Mudah diuji tanpa perlu mencetak apa pun.
- `cetakStruk` mengurus tampilan, dan memakai `hitungTotal` untuk angkanya.
- Kalau pajak berubah, cukup ubah `config.js`.

Di tantangan, kamu menyambungkan semua module ini di `main.js` dan menambahkan diskon.

