// === config.js ===
export const PAJAK = 0.1;
export const MIN_DISKON = 50000;
// === menu.js ===
const daftar = { kopi: 18000, teh: 12000, roti: 15000 };
export const hargaMenu = (nama) => daftar[nama];
// === keranjang.js ===
import { hargaMenu } from "./menu.js";
const isi = new Map();
export function tambah(nama, qty = 1) {
  isi.set(nama, (isi.get(nama) ?? 0) + qty);
}
export function item() {
  return [...isi].map(([nama, qty]) => ({ nama, qty, subtotal: hargaMenu(nama) * qty }));
}
// === struk.js ===
import { PAJAK, MIN_DISKON } from "./config.js";
const rp = (n) => "Rp" + n.toLocaleString("id-ID");
export function cetakStruk(daftarItem) {
  const subtotal = daftarItem.reduce((t, i) => t + i.subtotal, 0);
  const diskon = subtotal >= MIN_DISKON ? Math.round(subtotal * 0.1) : 0;
  const pajak = Math.round((subtotal - diskon) * PAJAK);
  for (const i of daftarItem) console.log(`${i.nama} x${i.qty}: ${rp(i.subtotal)}`);
  console.log(`Diskon: ${rp(diskon)}`);
  console.log(`Pajak: ${rp(pajak)}`);
  console.log(`Total: ${rp(subtotal - diskon + pajak)}`);
}
// === main.js ===
// import tambah dan item dari keranjang.js, serta cetakStruk dari struk.js

